import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"HDFC Securities","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/hdfc-securities.md","filePath":"connect-brokers/brokers/hdfc-securities.md"}'),s={name:"connect-brokers/brokers/hdfc-securities.md"};function n(i,e,c,p,d,l){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="hdfc-securities" tabindex="-1">HDFC Securities <a class="header-anchor" href="#hdfc-securities" aria-label="Permalink to &quot;HDFC Securities&quot;">​</a></h1><p>HDFC Securities InvestRight is the full-service broking platform from HDFC Securities, offering equity, F&amp;O, currency and commodity trading. Its <strong>InvestRight Open API</strong> exposes a REST API for orders, positions, holdings, funds and LTP snapshots, plus a Protobuf WebSocket feed for live market data. The developer portal and documentation are at <a href="https://developer.hdfcsec.com" target="_blank" rel="noreferrer">https://developer.hdfcsec.com</a>.</p><p>The integration process involves logging in to the InvestRight developer portal, creating an app to generate the API Key and API Secret, and configuring them in Tradeboard&#39;s environmental variables.</p><p><strong>Prerequisites</strong></p><p>Before proceeding with authentication, please make sure you have:</p><ol><li>A valid HDFC Securities InvestRight trading account (Client ID / registered Email / Mobile number)</li><li>Your registered mobile and email available to receive the login OTP</li><li>Registered your redirect URL in the developer portal (created inside the <strong>My Apps</strong> section)</li><li>A static IP address ready (mandatory as per the latest SEBI Circular; the app form asks for it)</li><li>Your application credentials, <strong>API Key</strong> and <strong>API Secret</strong>, handy (generated after you create and activate the app)</li></ol><p><strong>App Registration</strong></p><p>Goto the HDFC Securities InvestRight developer portal at <a href="https://developer.hdfcsec.com" target="_blank" rel="noreferrer">https://developer.hdfcsec.com</a> and log in with your credentials.</p><p>Step 1: On the home page, click the <strong>Login</strong> button in the top-right corner.</p><p>Step 2: On the Login screen, enter your <strong>Client ID / Email ID / Mobile No.</strong> and click submit.</p><p>Step 3: Enter the <strong>4 digit OTP</strong> sent to your registered mobile number and email ID to complete the login.</p><p>Step 4: After login, a <strong>My Apps</strong> menu item appears in the top navigation bar. Click on it.</p><p>Step 5: In the <strong>My Apps</strong> section, click the <strong>+ Create</strong> button to open the <strong>New App</strong> form.</p><p>Step 6: Fill in the form with required details.</p><ul><li><strong>App Name</strong>: a name to identify your app, for example <code>tradeboard</code></li><li><strong>Redirect URL</strong>: <code>https://tradeboard.local/hdfcsecurities/callback</code></li><li><strong>Postback URL</strong>: an optional URL for order postback notifications (a dummy URL is acceptable; Tradeboard does not consume postbacks)</li><li><strong>Primary Static IP</strong>: your static IP, now mandatory as per the SEBI circular</li><li><strong>Secondary Static IP</strong>: an optional backup static IP address</li><li><strong>Description</strong>: a short description of your app, for example <code>tradeboard</code></li><li><strong>APIs in this app</strong>: keep <strong>Trading API</strong> selected (it enables placing orders and reading the order book, positions and holdings)</li></ul><p>Step 7: Click <strong>Create</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Your created app will be deactivated by default. Go to the <strong>My Apps</strong> section and activate it before using the credentials.</p></div><p>Step 8: In the <strong>My Apps</strong> list, confirm the app status shows <strong>Active</strong>. Reveal (eye icon) and copy the generated <strong>API Key</strong> and <strong>API Secret</strong>.</p><p>Here is a sample of how the details would appear in a .env file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_api_key_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_api_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;https://tradeboard.local/hdfcsecurities/callback&#39;</span></span></code></pre></div><p>By integrating HDFC Securities InvestRight with Tradeboard you can automate order placement, monitor positions and stream live market data across all Tradeboard surfaces. As a best practice, keep your API Key and API Secret out of version control, restrict them to your registered static IP, and rotate them from the developer portal if you suspect they have been exposed.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/hdfcsecurities/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,24)])])}const u=t(s,[["render",n]]);export{h as __pageData,u as default};
